import { test, expect } from '@playwright/test';

test.describe('Row Badge Count Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display correct badge count for selected rows', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table headers are present
    const headers = page.getByRole('heading', { name: /row/i });
    await expect(headers).toBeVisible();

    // Verify first row is visible
    const firstRow = page.getByRole('row', { name: /row 1/i });
    await expect(firstRow).toBeVisible();

    // Verify badge count is not visible initially
    const badgeCount = page.getByRole('status', { name: /selected/i });
    await expect(badgeCount).not.toBeVisible();

    // Select the first row using getByRole
    const selectButton = page.getByRole('button', { name: /select/i });
    await selectButton.click();

    // Verify badge count is now visible
    await expect(badgeCount).toBeVisible();

    // Verify badge count text is correct
    const badgeText = page.getByText(/1 selected/i);
    await expect(badgeText).toBeVisible();

    // Verify badge count is updated when selecting another row
    const secondRow = page.getByRole('row', { name: /row 2/i });
    await secondRow.click();

    // Verify badge count is updated
    await expect(badgeText).toContainText(/2 selected/i);

    // Verify badge count is removed when deselecting a row
    const deselectButton = page.getByRole('button', { name: /deselect/i });
    await deselectButton.click();

    // Verify badge count is removed
    await expect(badgeText).not.toBeVisible();

    // Verify badge count is restored when deselecting all rows
    const deselectAllButton = page.getByRole('button', { name: /deselect all/i });
    await deselectAllButton.click();

    // Verify badge count is restored
    await expect(badgeText).toBeVisible();
    await expect(badgeText).toContainText(/1 selected/i);
  });

  test('should handle edge case: no rows selected', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify no badge count is displayed initially
    const badgeCount = page.getByRole('status', { name: /selected/i });
    await expect(badgeCount).not.toBeVisible();

    // Verify badge count is displayed when selecting a row
    const firstRow = page.getByRole('row', { name: /row 1/i });
    await firstRow.click();

    // Verify badge count is displayed
    await expect(badgeCount).toBeVisible();

    // Verify badge count text is correct
    const badgeText = page.getByText(/1 selected/i);
    await expect(badgeText).toBeVisible();

    // Verify badge count is not displayed when deselecting all rows
    const deselectAllButton = page.getByRole('button', { name: /deselect all/i });
    await deselectAllButton.click();

    // Verify badge count is removed
    await expect(badgeText).not.toBeVisible();

    // Verify badge count is restored when selecting a row again
    await firstRow.click();

    // Verify badge count is restored
    await expect(badgeText).toBeVisible();
    await expect(badgeText).toContainText(/1 selected/i);
  });
});
